import {readMachineActivity} from './src/lib/machine-lane-activity.ts';
const source=process.argv[1]; const before=Object.getOwnPropertyNames(Object.prototype);
const read=()=>{try{return readMachineActivity(source,'msx')}catch(error){return {error:String(error)}}};
const result=read(); const empty=readMachineActivity('','msx');
console.log(JSON.stringify({source,result,empty,prototypeAdded:Object.getOwnPropertyNames(Object.prototype).filter(k=>!before.includes(k))}));
